PREFIX ps:      <https://w3id.org/mintjesba/pefdpp/pefstudy#>
PREFIX prs:     <https://w3id.org/mintjesba/pefdpp/product-system#>
PREFIX act:     <https://w3id.org/mintjesba/pefdpp/activity#>
PREFIX flow:    <https://w3id.org/mintjesba/pefdpp/flow#>
PREFIX dataset: <https://w3id.org/mintjesba/pefdpp/dataset#>
PREFIX dq:      <https://w3id.org/mintjesba/pefdpp/dataquality#>
PREFIX om:      <http://www.ontology-of-units-of-measure.org/resource/om-2/>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs:    <http://www.w3.org/2000/01/rdf-schema#>
PREFIX foaf:    <http://xmlns.com/foaf/0.1/>
PREFIX skos:    <http://www.w3.org/2004/02/skos/core#>

SELECT ?what ?howWell ?amount ?unit ?conversion ?referenceFlow WHERE {
  ?fu a ps:FunctionalUnit ;
      ps:whatProvided ?what ;
      ps:howWellProvided ?howWell ;
      ps:howMuchProvided ?m ;
      ps:RFtoFUConversion ?conversion ;
      ps:hasReferenceFlow ?referenceFlow .
  ?m om:hasNumericalValue ?amount ; om:hasUnit ?unit .
}

PREFIX ps:      <https://w3id.org/mintjesba/pefdpp/pefstudy#>
PREFIX prs:     <https://w3id.org/mintjesba/pefdpp/product-system#>
PREFIX act:     <https://w3id.org/mintjesba/pefdpp/activity#>
PREFIX flow:    <https://w3id.org/mintjesba/pefdpp/flow#>
PREFIX dataset: <https://w3id.org/mintjesba/pefdpp/dataset#>
PREFIX dq:      <https://w3id.org/mintjesba/pefdpp/dataquality#>
PREFIX om:      <http://www.ontology-of-units-of-measure.org/resource/om-2/>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs:    <http://www.w3.org/2000/01/rdf-schema#>
PREFIX foaf:    <http://xmlns.com/foaf/0.1/>
PREFIX skos:    <http://www.w3.org/2004/02/skos/core#>

SELECT ?application ?context ?commissioner ?verifier WHERE {
  ?g a ps:Goal ;
     ps:intendedApplication ?application ;
     ps:decisionContext ?context ;
     ps:commissioner ?cIri ;
     ps:verifier ?vIri .
  OPTIONAL { ?cIri foaf:name ?cName }
  OPTIONAL { ?vIri foaf:name ?vName }
  BIND(COALESCE(?cName, STR(?cIri)) AS ?commissioner)
  BIND(COALESCE(?vName, STR(?vIri)) AS ?verifier)
}

