PREFIX foaf:    <http://xmlns.com/foaf/0.1/>
PREFIX skos:    <http://www.w3.org/2004/02/skos/core#>

SELECT ?boundaryType ?cutOff ?justification ?excludes WHERE {
  ?sb a ps:SystemBoundary ;
      ps:hasBoundaryType ?boundaryType ;
      ps:cutOffCriteria ?cutOff ;
      ps:hasJustification ?justification .
  OPTIONAL { ?sb ps:excludesActivity ?excludes }
}

