PREFIX prs:     <https://w3id.org/mintjesba/pefdpp/product-system#>
PREFIX act:     <https://w3id.org/mintjesba/pefdpp/activity#>
PREFIX flow:    <https://w3id.org/mintjesba/pefdpp/flow#>
PREFIX dataset: <https://w3id.org/mintjesba/pefdpp/dataset#>
PREFIX dq:      <https://w3id.org/mintjesba/pefdpp/dataquality#>
PREFIX om:      <http://www.ontology-of-units-of-measure.org/resource/om-2/>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs:    <http://www.w3.org/2000/01/rdf-schema#>
PREFIX foaf:    <http://xmlns.com/foaf/0.1/>
PREFIX skos:    <http://www.w3.org/2004/02/skos/core#>

SELECT ?label ?amount ?R2 ?R3 ?virginEquivalent ?recyclingFlow ?disposalFlow WHERE {
  ?flow flow:hasEndOfLifeScenario ?eol ; flow:hasMeasure ?m .
  OPTIONAL { ?flow flow:contextualLabel ?label }
  ?m om:hasNumericalValue ?amount .
  OPTIONAL { ?eol flow:recyclingRate ?r2n . ?r2n flow:hasValue ?R2 }
  OPTIONAL { ?eol flow:energyRecoveryRate ?r3n . ?r3n flow:hasValue ?R3 }
  OPTIONAL { ?eol flow:virginEquivalent ?virginEquivalent }
  OPTIONAL { ?eol flow:recyclingFlowType ?recyclingFlow }
  OPTIONAL { ?eol flow:disposalFlowType ?disposalFlow }
}
